CustomField.formula:
IF(TEXT(CurrencyIsoCode) = 'PHP',
    Opportunity__r.Addressable_Merchant_Revenue_Monthly__c / CURRENCYRATE('PHP'),
    IF(TEXT(CurrencyIsoCode) = 'IDR',
        Opportunity__r.Addressable_Merchant_Revenue_Monthly__c / CURRENCYRATE('IDR'),
        IF(TEXT(CurrencyIsoCode) = 'MYR',
            Opportunity__r.Addressable_Merchant_Revenue_Monthly__c / CURRENCYRATE('MYR'),
            IF(TEXT(CurrencyIsoCode) = 'SGD',
                Opportunity__r.Addressable_Merchant_Revenue_Monthly__c / CURRENCYRATE('SGD'),
                IF(TEXT(CurrencyIsoCode) = 'THB',
                    Opportunity__r.Addressable_Merchant_Revenue_Monthly__c / CURRENCYRATE('THB'),
                    IF(TEXT(CurrencyIsoCode) = 'VND',
                        Opportunity__r.Addressable_Merchant_Revenue_Monthly__c / CURRENCYRATE('VND'),
                        Opportunity__r.Addressable_Merchant_Revenue_Monthly__c
                    )
                )
            )
        )
    )
)
